def game_score(points: str) -> str:
    # Map numeric score to display string
    score_map = {0: "0", 1: "15", 2: "30", 3: "40"}
    # Current scores in points (0-3)
    scores = {"A": 0, "B": 0}
    winner = None

    for p in points:
        if p not in ("A", "B"):
            continue  # ignore unexpected characters
        if winner is not None:
            break  # ignore points after the game is decided

        scores[p] += 1

        # Check if the game has been won
        a, b = scores["A"], scores["B"]
        # Normal win: one player has 4 points
        if a == 4:
            winner = "A"
        elif b == 4:
            winner = "B"
        # No‑ad rule: if both reach 3 (40-40), next point wins
        elif a == 3 and b == 3:
            # The next point in the loop will increment one side to 4,
            # which will be caught by the above condition.
            pass

    if winner:
        return f"Game {winner}"
    else:
        a, b = scores["A"], scores["B"]
        return f"{score_map[a]}-{score_map[b]}"
